INPUT: finite set D (the group), read-outs g, k
OUTPUT: H(g), H(k), H(g|k), H(k|g), I(g;k)

function ENTROPY(counts):
    N <- sum(counts)
    return -sum over c in counts with c > 0 of (c/N) * log2(c/N)

function FIBRES(D, f):
    B <- empty map from values to lists
    for x in D: append x to B[f(x)]
    return B

function CHANNEL(D, g, k):
    N <- |D|
    H_g <- ENTROPY(sizes of FIBRES(D, g))
    H_k <- ENTROPY(sizes of FIBRES(D, k))
    H_g_given_k <- 0
    for each block B in FIBRES(D, k):
        H_g_given_k <- H_g_given_k + (|B|/N) * ENTROPY(sizes of FIBRES(B, g))
    H_k_given_g <- 0
    for each block B in FIBRES(D, g):
        H_k_given_g <- H_k_given_g + (|B|/N) * ENTROPY(sizes of FIBRES(B, k))
    return (H_g, H_k, H_g_given_k, H_k_given_g, H_g - H_g_given_k)

algorithms.code:
"""Exact evaluation of the Chebotarev information channel of a finite group.

Given a finite group presented as a list of elements together with two
read-outs g (e.g. the splitting type / conjugacy class) and k (e.g. an abelian
character), this computes the uniform (Chebotarev) entropies

    H(g),  H(k),  H(g | k),  I(g ; k) = H(g) - H(g | k)

by exact fibre counting.  Complexity is O(|G|) hash operations and O(|G|)
memory; no sampling and no arithmetic over number fields are involved.
"""

from __future__ import annotations

from collections import defaultdict
from math import log2
from typing import Callable, Dict, Hashable, Iterable, List, Sequence, Tuple


def entropy_of_counts(counts: Iterable[int]) -> float:
    """Shannon entropy (bits) of the distribution proportional to `counts`."""
    cs: List[int] = [c for c in counts if c > 0]
    total: int = sum(cs)
    if total == 0:
        return 0.0
    return -sum((c / total) * log2(c / total) for c in cs)


def fibres(
    domain: Sequence[Hashable], f: Callable[[Hashable], Hashable]
) -> Dict[Hashable, List[Hashable]]:
    """Partition `domain` into the fibres of `f`."""
    blocks: Dict[Hashable, List[Hashable]] = defaultdict(list)
    for x in domain:
        blocks[f(x)].append(x)
    return blocks


def channel_report(
    domain: Sequence[Hashable],
    g: Callable[[Hashable], Hashable],
    k: Callable[[Hashable], Hashable],
) -> Dict[str, float]:
    """Return H(g), H(k), H(g|k), H(k|g) and I(g;k) for the uniform measure."""
    n: int = len(domain)
    H_g: float = entropy_of_counts(len(b) for b in fibres(domain, g).values())
    H_k: float = entropy_of_counts(len(b) for b in fibres(domain, k).values())
    H_g_given_k: float = sum(
        (len(b) / n) * entropy_of_counts(len(c) for c in fibres(b, g).values())
        for b in fibres(domain, k).values()
    )
    H_k_given_g: float = sum(
        (len(b) / n) * entropy_of_counts(len(c) for c in fibres(b, k).values())
        for b in fibres(domain, g).values()
    )
    return {
        "H(g)": H_g,
        "H(k)": H_k,
        "H(g|k)": H_g_given_k,
        "H(k|g)": H_k_given_g,
        "I(g;k)": H_g - H_g_given_k,
    }


if __name__ == "__main__":
    from itertools import permutations

    def cycle_type(p: Tuple[int, ...]) -> Tuple[int, ...]:
        n, seen, parts = len(p), [False] * len(p), []
        for i in range(n):
            if not seen[i]:
                length, j = 0, i
                while not seen[j]:
                    seen[j] = True
                    j = p[j]
                    length += 1
                parts.append(length)
        return tuple(sorted(parts, reverse=True))

    def sign(p: Tuple[int, ...]) -> int:
        return (-1) ** sum(c - 1 for c in cycle_type(p))

    G: List[Tuple[int, ...]] = [tuple(p) for p in permutations(range(3))]
    for name, value in channel_report(G, cycle_type, sign).items():
        print(f"{name:>8} = {value:.10f}")

