INPUT: multiplication table mul, inversion table inv, character chi, |C|
OUTPUT: certified ceiling log2 |C|, H(class), exact deficit, validity flag

function CONJUGACY_CLASSES(mul, inv):
    label[x] <- unassigned for all x
    for x in G with label[x] unassigned:
        block <- { mul[mul[c][x]][inv[c]] : c in G }
        assign a fresh label to every y in block
    return the blocks

function CERTIFY(mul, inv, chi, cardC):
    fibre_size[v] <- #{ x : chi[x] = v }
    surjective <- (number of distinct values of chi = cardC)
    balanced   <- for all v: cardC * fibre_size[v] = |G|
    classfn    <- for every conjugacy class B: chi is constant on B
    H_class    <- ENTROPY(sizes of CONJUGACY_CLASSES(mul, inv))
    ceiling    <- log2(cardC)
    assert surjective and balanced and classfn
    return (ceiling, H_class, H_class - ceiling)

GUARANTEE: for every map u defined on C,
    I(conjugacy class ; u o chi) <= ceiling, with equality for u = identity.
